#include "TextureDocument.hh"
#include "StrokeArchive.hh"
#include <cassert>
#include <iostream>
using namespace bts;
int main(){
 SceneSnapshot scene;ImportSummary imported;for(int i=1;i<=2;++i){MaterialSummary m;m.session_id=i;m.name=i==1?"Source":"Target";m.uniform_editable=true;scene.materials.push_back(m);imported.materials.push_back({std::uint32_t(i),m.name});}TextureDocument doc({},imported,scene);auto &source=doc.set(1);auto &target=doc.set(2);for(auto *set:{&source,&target}){TextureDocument::set_resolution(*set,128);set->precision[0]=ChannelPrecision::RGB32F;}
 TextureDocument::add_fill(source);const auto fill=source.selected_layer;auto &original=TextureDocument::layer(source,fill);original.values.base_color={.2,.4,.6,1};original.blending[0]=LayerBlend::Screen;TextureDocument::add_fill(target);TextureDocument::layer(target,target.selected_layer).values.base_color={.4,.2,.1,1};const auto instance=TextureDocument::add_instance(target,source.id,fill,original.name);doc.resolve_instances();
 const auto check=[&](const TextureSet &set,std::array<float,3> expected){const auto result=TextureDocument::evaluate(set,64,64).material.base_color;for(int c=0;c<3;++c)assert(std::abs(result[c]-expected[c])<1e-6);};check(target,{.52,.52,.64});assert(TextureDocument::layer(source,fill).blending[0]==LayerBlend::Screen&&TextureDocument::layer(target,instance).blending[0]==LayerBlend::Passthrough);
 auto snapshot=doc;const auto before_signature=TextureDocument::mask_dependency_signature(target);TextureDocument::layer(source,fill).values.base_color[0]=.8;doc.resolve_instances();assert(TextureDocument::mask_dependency_signature(target)!=before_signature);check(target,{.88,.52,.64});check(snapshot.set(2),{.52,.52,.64});TextureDocument::layer(target,instance).opacity[0]=.5;doc.resolve_instances();check(target,{.64,.36,.37});TextureDocument::layer(target,instance).opacity[0]=1;
 TextureDocument::add_paint(source);const auto paint=source.selected_layer;auto &raster=TextureDocument::layer(source,paint);PaintPixels::Stamp stamp{{.5,.5},{.2,0},{0,.2}};stamp.channels={true,false,false,false,false};stamp.values.base_color={1,1,1,1};raster.pixels.stamp(128,stamp,source.tiles);const auto paint_instance=TextureDocument::add_instance(target,source.id,paint,raster.name);doc.resolve_instances();check(target,{.88,.52,.64});const auto &expanded=evaluation_layers(target);const auto derived=std::find_if(expanded.begin(),expanded.end(),[&](const auto &layer){return layer.id==paint_instance;});assert(derived!=expanded.end()&&derived->pixels.empty());TextureDocument::add_instance(source,source.id,paint,raster.name);doc.resolve_instances();assert(!evaluation_layers(source).back().pixels.empty());
 source.selected_layer=fill;TextureDocument::group_layers(source,{fill});const auto folder=source.selected_layer;const auto folder_instance=TextureDocument::add_instance(target,source.id,folder,"Source folder");doc.resolve_instances();assert(target.instance_problems.empty());const auto &group=evaluation_layers(target).back();assert(group.id==folder_instance&&group.kind==LayerKind::Folder&&group.depth==0);assert(evaluation_layers(target)[evaluation_layers(target).size()-2].parent==folder_instance);
 const auto valid=doc;source.selected_layer=fill;const auto cyclic=TextureDocument::add_instance(source,source.id,folder,"Source folder");doc.resolve_instances();assert(source.instance_problems.contains(cyclic)&&source.instance_problems.contains(folder)&&target.instance_problems.contains(folder_instance));assert(!evaluation_layers(target).back().visible);doc=valid;doc.resolve_instances();assert(doc.set(2).instance_problems.empty());
 const auto json=doc.to_json();std::vector<TextureSetBinding> bindings;for(const auto &set:doc.texture_sets())bindings.push_back({set.id,set.material_session_uid,set.name});auto loaded=TextureDocument::from_json(json,bindings);for(const auto &set:doc.texture_sets())for(const auto &layer:set.layers){auto &restored=TextureDocument::layer(loaded.set(set.material_session_uid),layer.id);restored.pixels=layer.pixels;restored.ao_pixels=layer.ao_pixels;}read_stroke_archive(loaded,write_stroke_archive(doc));loaded.resolve_instances();assert(loaded.to_json()==json&&loaded.set(2).instance_layers&&loaded.set(2).instance_problems.empty());
 auto &broken=TextureDocument::layer(loaded.set(2),folder_instance);const auto missing=QUuid::createUuid();broken.instance->source_set=missing;loaded.resolve_instances();assert(loaded.set(2).instance_problems.contains(folder_instance)&&broken.instance->source_set==missing);
 bool rejected=false;try{read_layer_instance(QJsonObject{{"set","invalid"},{"layer",fill.toString()}});}catch(const std::invalid_argument &){rejected=true;}assert(rejected);
 std::cout<<"Live UUID source, source Screen vs target Passthrough, opacity, COW snapshot, cross-set paint discard, same-set paint, folder expansion, retained cycles, metadata and missing sources passed\n";
}
